<?php
declare(strict_types=1);namespace EnglAI\Learning;
final class WritingSessionService{
public const TASKS=10;public function __construct(private readonly \PDO $pdo){}
private function normalize(string $text):string{$text=mb_strtolower(trim($text));$text=preg_replace('/\b(please|kindly|write|make|create|describe|describing|sentence|about|appearance|using|use|one|a|an|the|in)\b/u',' ',$text)??$text;$text=preg_replace('/[^\pL\pN\s]/u',' ',$text)??$text;return trim(preg_replace('/\s+/u',' ',$text)??$text);}
private function fingerprint(array $row,array $content,string $level):string{$prompt=$this->normalize((string)($content['prompt']??''));$keywords=array_map(fn($v)=>$this->normalize((string)$v),$content['keywords']??[]);sort($keywords);$objective=preg_match('/compare|difference|similar/u',$prompt)?'comparison':(preg_match('/why|reason|because|cause/u',$prompt)?'reason':(preg_match('/recommend|should|solution/u',$prompt)?'recommendation':(preg_match('/describe|appearance|characteristic/u',$prompt)?'description':'response')));$topic=implode(' ',array_slice(array_values(array_unique(array_filter(array_merge($keywords,preg_split('/\s+/u',$prompt)?:[])))),0,8));$type=$level==='basic'?'sentence_writing':($level==='intermediate'?'guided_writing':'short_open_response');return hash('sha256',implode('|',[$level,$type,$objective,$topic,implode(',',$keywords),$prompt]));}
public function get(int $id,int $member,int $classroom):array{$q=$this->pdo->prepare('SELECT * FROM writing_sessions WHERE id=? AND member_id=? AND classroom_id=?');$q->execute([$id,$member,$classroom]);$s=$q->fetch();if(!$s)throw new \RuntimeException('Writing session tidak ditemukan.');return $s;}
public function start(int $member,int $classroom,string $level,bool $new=false):array{$level=Level::validate($level);$planQ=$this->pdo->prepare('SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$planQ->execute([$classroom]);$plan=(int)$planQ->fetchColumn();if(!$new&&$plan){$q=$this->pdo->prepare("SELECT * FROM writing_sessions WHERE member_id=? AND classroom_id=? AND lesson_plan_id=? AND level=? AND status='active' ORDER BY id DESC LIMIT 1");$q->execute([$member,$classroom,$plan,$level]);if($s=$q->fetch())return $s;}$q=$this->pdo->prepare('SELECT id FROM classroom_lesson_plans WHERE classroom_id=? AND is_active=1 ORDER BY version DESC LIMIT 1');$q->execute([$classroom]);$plan=(int)$q->fetchColumn();$q=$this->pdo->prepare("SELECT id,title,instruction,content_json FROM learning_activities WHERE classroom_id=? AND lesson_plan_id=? AND skill='writing' AND level=? AND status='ready' ORDER BY id");$q->execute([$classroom,$plan,$level]);$unique=[];foreach($q->fetchAll() as $r){$c=json_decode((string)$r['content_json'],true)?:[];$p=trim((string)($c['prompt']??''));if($p==='')continue;$finger=$this->fingerprint($r,$c,$level);$norm=$this->normalize($p);if(!isset($unique[$finger])&&!isset($unique['prompt:'.$norm])){$r['_finger']=$finger;$r['_content']=$c;$unique[$finger]=$r;$unique['prompt:'.$norm]=true;}}$items=array_values(array_filter($unique,'is_array'));if(count($items)<self::TASKS)throw new \RuntimeException('Materi Writing untuk level ini sedang disiapkan oleh Teacher.');$h=$this->pdo->prepare('SELECT task_id,MAX(submitted_at) used FROM writing_submissions WHERE member_id=? AND classroom_id=? GROUP BY task_id');$h->execute([$member,$classroom]);$used=array_column($h->fetchAll(),'used','task_id');foreach($items as &$r)$r['_tie']=random_int(1,PHP_INT_MAX);unset($r);usort($items,fn($a,$b)=>strcmp((string)($used[$a['id']]??''),(string)($used[$b['id']]??''))?:($a['_tie']<=>$b['_tie']));$pool=array_slice($items,0,max(10,min(count($items),20)));$previous=$this->pdo->prepare('SELECT sequence_fingerprint FROM writing_sessions WHERE member_id=? AND classroom_id=? AND level=? ORDER BY id DESC LIMIT 1');$previous->execute([$member,$classroom,$level]);$last=(string)$previous->fetchColumn();for($try=0;$try<12;$try++){shuffle($pool);$selected=array_slice($pool,0,10);$sequence=hash('sha256',implode(',',array_column($selected,'id')));if($sequence!==$last||count($pool)===10)break;}$snap=[];foreach($selected as $i=>$r){$c=$r['_content'];$type=$level==='basic'?'sentence_writing':($level==='intermediate'?'guided_writing':'short_open_response');$instruction=$level==='basic'?['Tulislah satu kalimat bahasa Inggris berdasarkan prompt berikut.','Gunakan vocabulary berikut dalam satu kalimat sederhana.','Jawablah prompt berikut dengan satu kalimat bahasa Inggris.'][$i%3]:($level==='intermediate'?['Tulislah dua kalimat singkat menggunakan bantuan yang tersedia.','Jelaskan jawabanmu dalam dua kalimat bahasa Inggris.','Lanjutkan gagasan berikut secara singkat.'][$i%3]:['Tulislah pendapat singkat dalam dua sampai tiga kalimat.','Jelaskan alasan atau solusi secara ringkas.','Berikan rekomendasi singkat dalam bahasa Inggris.'][$i%3]);$snap[]=['position'=>$i,'id'=>(int)$r['id'],'fingerprint'=>$r['_finger'],'type'=>$type,'instruction'=>$instruction,'prompt'=>(string)$c['prompt'],'context'=>(string)($c['context']??''),'guidance'=>implode(', ',array_slice(array_map('strval',$c['keywords']??[]),0,4)),'sentence_starter'=>(string)($c['sentence_starter']??''),'example_answer'=>(string)($c['example_answer']??''),'max_chars'=>$level==='basic'?300:($level==='intermediate'?600:900)];}$this->pdo->prepare('INSERT INTO writing_sessions(classroom_id,member_id,lesson_plan_id,level,task_snapshot_json,sequence_fingerprint,started_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$classroom,$member,$plan,$level,json_encode($snap,JSON_UNESCAPED_UNICODE),$sequence]);return $this->get((int)$this->pdo->lastInsertId(),$member,$classroom);}
public function state(array $s):array{$tasks=json_decode((string)$s['task_snapshot_json'],true)?:[];$q=$this->pdo->prepare('SELECT * FROM writing_submissions WHERE session_id=? ORDER BY id');$q->execute([$s['id']]);$subs=$q->fetchAll();$c=$this->pdo->prepare('SELECT UNIX_TIMESTAMP(task_started_at)*1000 started_ms,UNIX_TIMESTAMP(task_deadline_at)*1000 deadline_ms FROM writing_sessions WHERE id=?');$c->execute([$s['id']]);$clock=$c->fetch()?:[];$pos=(int)$s['current_position'];return ['id'=>(int)$s['id'],'level'=>$s['level'],'status'=>$s['status'],'position'=>$pos,'total'=>10,'task'=>$s['status']==='active'?($tasks[$pos]??null):null,'task_started_epoch_ms'=>isset($clock['started_ms'])?(int)$clock['started_ms']:null,'task_deadline_epoch_ms'=>isset($clock['deadline_ms'])?(int)$clock['deadline_ms']:null,'tasks'=>$s['status']==='completed'?$tasks:[],'submissions'=>$s['status']==='completed'?$subs:[],'average_score'=>$subs?round(array_sum(array_map(fn($r)=>(float)($r['score']??0),$subs))/max(1,count(array_filter($subs,fn($r)=>$r['score']!==null))),1):0];}}
